+
+  async function investigate() {
+    if (!ready) { setError("Add the required PDFs and enter each document’s printed ID before investigating."); return; }
+    setResult(null); setError(""); setDemoInfo(""); setStage("extracting");
+    const prepared: Doc[] = [];
+    try {
