+      revised: { files: [["contract", "contract.pdf"], ["amendment", "amendment.pdf"], ["purchase_order", "purchase-order-amended.pdf"], ["invoice", "invoice.pdf"]], ids: ["C-001", "AM-001", "PO-018", "INV-104"] }
+    };
+    const scenario = scenarios[name]; const loaded: Doc[] = [];
+    try {
