+      <div className="card findings-card"><div className="section-head"><div><div className="step">LINE ITEM REVIEW</div><h2>Price comparisons</h2></div><span className="quiet-pill">All amounts INR</span></div>{result.case.findings.length === 0 ? <div className="zero-findings"><span className="zero-check">✓</span><div><strong>No findings in checked lines</strong><p>The completed case found no potential overcharge for the supplied documents.</p></div></div> : result.case.findings.map((f, i) => <article className="finding-row" key={`${f.invoiceId}-${f.sku}-${i}`}><div className="finding-head"><strong>{f.invoiceId} <span>·</span> {f.sku}</strong><span className={f.status === "needs_review" ? "finding-tag review-tag" : "finding-tag"}>{f.status === "needs_review" ? "REVIEW" : "POTENTIAL OVERCHARGE"}</span></div><p>{f.reason}</p><div className="comparison"><div><small>Contract benchmark</small><strong>{f.expectedUnitPrice === undefined ? "Not established" : `${fmt(f.expectedUnitPrice)} / unit`}</strong></div><b aria-hidden="true">→</b><div><small>Invoice unit price</small><strong>{fmt(f.billedUnitPrice)} / unit</strong></div><div><small>Quantity</small><strong>{f.quantity.toLocaleString("en-IN")}</strong></div><div className="line-total"><small>Potential line amount</small><strong>{f.potentialOvercharge === undefined ? "Review required" : fmt(f.potentialOvercharge)}</strong></div></div></article>)}</div></>}
